static const struct custom_map_sector CUSTOM_MAP_SECTORS[] = {
    { 0, 49, 47, CMH_0, CMC_0, CMD_0, CMNS_0, CMEW_0, CMRF_0, CMDG_0 },
    { 0, 51, 51, CMH_1, CMC_1, CMD_1, CMNS_1, CMEW_1, CMRF_1, CMDG_1 },
    { 0, 54, 46, CMH_2, CMC_2, CMD_2, CMNS_2, CMEW_2, CMRF_2, CMDG_2 },
    { 0, 65, 46, CMH_3, CMC_3, CMD_3, CMNS_3, CMEW_3, NULL, NULL },
    { 0, 65, 47, CMH_4, CMC_4, CMD_4, NULL, NULL, NULL, NULL },
    { 0, 66, 46, CMH_5, CMC_5, CMD_5, CMNS_5, NULL, NULL, NULL },
    { 0, 66, 47, CMH_6, CMC_6, CMD_6, NULL, NULL, NULL, NULL },
    { 0, 68, 40, CMH_7, CMC_7, CMD_7, CMNS_7, CMEW_7, CMRF_7, CMDG_7 },
    { 1, 68, 40, CMH_8, CMC_8, CMD_8, CMNS_8, CMEW_8, CMRF_8, NULL },
    { 3, 53, 47, CMH_9, CMC_9, CMD_9, CMNS_9, CMEW_9, NULL, CMDG_9 },
    { 3, 54, 49, CMH_10, CMC_10, CMD_10, CMNS_10, CMEW_10, NULL, CMDG_10 },
};

static const int CUSTOM_MAP_SECTOR_COUNT = sizeof(CUSTOM_MAP_SECTORS) / sizeof(CUSTOM_MAP_SECTORS[0]);

int custom_maps_landscape_fill(int plane, int sx, int sy,
                               int8_t *terrain_height, int8_t *terrain_colour,
                               int8_t *walls_north_south, int8_t *walls_east_west,
                               uint16_t *walls_diagonal, int8_t *walls_roof,
                               int8_t *tile_decoration, int8_t *tile_direction) {
    for (int i = 0; i < CUSTOM_MAP_SECTOR_COUNT; i++) {
        const struct custom_map_sector *rs = &CUSTOM_MAP_SECTORS[i];

        if (rs->plane != plane || rs->sx != sx || rs->sy != sy) {
            continue;
        }

        // height/colour/decoration always present
        for (int t = 0; t < 2304; t++) {
            terrain_height[t] = (int8_t)rs->height[t];
            terrain_colour[t] = (int8_t)rs->colour[t];
            tile_decoration[t] = (int8_t)rs->decoration[t];
        }

        // walls: copy if this sector has any, else clear
        if (rs->walls_ns != NULL) {
            for (int t = 0; t < 2304; t++) {
                walls_north_south[t] = (int8_t)rs->walls_ns[t];
            }
        } else {
            memset(walls_north_south, 0, 2304);
        }

        if (rs->walls_ew != NULL) {
            for (int t = 0; t < 2304; t++) {
                walls_east_west[t] = (int8_t)rs->walls_ew[t];
            }
        } else {
            memset(walls_east_west, 0, 2304);
        }

        if (rs->walls_roof != NULL) {
            for (int t = 0; t < 2304; t++) {
                walls_roof[t] = (int8_t)rs->walls_roof[t];
            }
        } else {
            memset(walls_roof, 0, 2304);
        }

        if (rs->walls_diag != NULL) {
            for (int t = 0; t < 2304; t++) {
                walls_diagonal[t] = rs->walls_diag[t];
            }
        } else {
            memset(walls_diagonal, 0, 2304 * sizeof(uint16_t));
        }

        memset(tile_direction, 0, 2304);

        return 1;
    }

    return 0;
}
